// 생성된 파일 — 손으로 고치지 않는다. 원본은 shared/server-text.ts, 다시 만들기: bun scripts/gen-server-text-swift.ts
import Foundation

/// 서버가 만든 글(시스템 글·결재 카드·활동 줄)의 코드별 틀을 화면 언어로. 영어는 문구 표의 server.text.*, 한국어는 기본값.
/// 그리기 규칙은 ServerText.swift. 모르는 코드는 nil(받은 문장을 그대로 보인다).
enum ServerTextCatalog {
    static func template(_ code: String) -> String? {
        switch code {
        case "chat.member_error": return String(localized: "server.text.chat.member_error", defaultValue: "{name} 오류: {error}")
        case "chat.run_interrupted": return String(localized: "server.text.chat.run_interrupted", defaultValue: "{name}: 실행 {run} 중단 — {why}")
        case "chat.run_restart_resumed": return String(localized: "server.text.chat.run_restart_resumed", defaultValue: "{name}: 실행 {run} — 재시작으로 끊겨 이어서 하게 했습니다")
        case "chat.usage_model_resumed": return String(localized: "server.text.chat.usage_model_resumed", defaultValue: "{name}: 실행 {run} — 사용 한도로 멈춰 모델을 {model:으로} 바꿔 이어서 하게 했습니다")
        case "chat.usage_account_resumed": return String(localized: "server.text.chat.usage_account_resumed", defaultValue: "{name}: 실행 {run} — 사용 한도로 멈춰 다른 계정으로 로그인한 뒤 같은 대화를 이어서 하게 했습니다")
        case "chat.login_resumed": return String(localized: "server.text.chat.login_resumed", defaultValue: "{name}: 실행 {run} — 로그인 오류로 멈춰 다시 로그인한 뒤 이어서 하게 했습니다")
        case "chat.missing_report": return String(localized: "server.text.chat.missing_report", defaultValue: "{name}의 결과 보고가 보완 요청 뒤에도 남지 않았습니다. 기존 업무를 다시 실행하지 않고 결과를 확인해 주세요.")
        case "chat.missing_report.title": return String(localized: "server.text.chat.missing_report.title", defaultValue: "결과 보고 누락")
        case "chat.quick_exit": return String(localized: "server.text.chat.quick_exit", defaultValue: "{name}의 세션이 시작하자마자 끝나기를 되풀이해 자동으로 다시 깨우지 않습니다. 터미널에서 원인을 확인한 뒤 팀원을 깨워 주세요.")
        case "chat.quick_exit_error": return String(localized: "server.text.chat.quick_exit_error", defaultValue: "{name}의 세션이 시작하자마자 끝나기를 되풀이해 자동으로 다시 깨우지 않습니다. 터미널에서 원인을 확인한 뒤 팀원을 깨워 주세요. ({error})")
        case "chat.owner_message_late": return String(localized: "server.text.chat.owner_message_late", defaultValue: "{name}에게 보낸 대표 메시지가 30분 넘게 전달되지 않았습니다. 전달 #{id}를 확인해 주세요.")
        case "chat.owner_message_late.title": return String(localized: "server.text.chat.owner_message_late.title", defaultValue: "대표 전달 지연")
        case "chat.owner_answer_late": return String(localized: "server.text.chat.owner_answer_late", defaultValue: "{name}에게 보낸 대표 결재 답이 30분 넘게 전달되지 않았습니다. 전달 #{id}를 확인해 주세요.")
        case "chat.owner_answer_late.title": return String(localized: "server.text.chat.owner_answer_late.title", defaultValue: "대표 전달 지연")
