        case "chat.owner_instruction_late.title": return String(localized: "server.text.chat.owner_instruction_late.title", defaultValue: "대표 전달 지연")
        case "chat.owner_todo_done_late": return String(localized: "server.text.chat.owner_todo_done_late", defaultValue: "{name}에게 보낸 할 일 완료 소식이 30분 넘게 전달되지 않았습니다. 팀 화면에서 {name}의 상태를 확인해 주세요.")
        case "chat.owner_todo_done_late.title": return String(localized: "server.text.chat.owner_todo_done_late.title", defaultValue: "대표 전달 지연")
